defmodule NeonPerceptron.PythonBenchTest do
  use ExUnit.Case, async: true

  alias NeonPerceptron.PythonBench

  describe "pack/1 — byte-for-byte equivalence with brendan-spi-test.py" do
    # Ground-truth byte sequences below were generated by running Brendan's
    # exact packing algorithm in Python 3 and recording the resulting
    # `buffer` list. Re-derive with:
    #
    #     def pack(leds):
    #         buf = [0] * 36
    #         idx = 35
    #         for i in range(0, 23, 2):
    #             a, b = min(leds[i], 4096), min(leds[i+1], 4096)
    #             buf[idx]   = a & 0xFF
    #             buf[idx-1] = ((a >> 8) & 0x0F) | ((b << 4) & 0xF0)
    #             buf[idx-2] = (b >> 4) & 0xFF
    #             idx -= 3
    #         return buf

    test "initial RGB sweep state (matches Python case A)" do
      # leds[18..20] = 1752 (3800 - 2048), leds[21..23] = 2048
      leds =
        List.duplicate(0, 24)
        |> List.replace_at(18, 1752)
        |> List.replace_at(19, 1752)
        |> List.replace_at(20, 1752)
        |> List.replace_at(21, 2048)
        |> List.replace_at(22, 2048)
        |> List.replace_at(23, 2048)

      expected =
        <<0x80, 0x08, 0x00, 0x80, 0x06, 0xD8, 0x6D, 0x86, 0xD8>> <>
          :binary.copy(<<0>>, 27)

      assert PythonBench.pack(leds) == expected
    end

    test "asymmetric values on first channel pair (matches Python case B)" do
      leds = [0xABC, 0x123] ++ List.duplicate(0, 22)
      expected = :binary.copy(<<0>>, 33) <> <<0x12, 0x3A, 0xBC>>
      assert PythonBench.pack(leds) == expected
    end

    test "every channel = its index (matches Python case C, catches off-by-one)" do
      leds = Enum.to_list(0..23)

      expected =
        <<0x01, 0x70, 0x16, 0x01, 0x50, 0x14, 0x01, 0x30, 0x12, 0x01, 0x10, 0x10, 0x00, 0xF0,
          0x0E, 0x00, 0xD0, 0x0C, 0x00, 0xB0, 0x0A, 0x00, 0x90, 0x08, 0x00, 0x70, 0x06, 0x00,
          0x50, 0x04, 0x00, 0x30, 0x02, 0x00, 0x10, 0x00>>

      assert PythonBench.pack(leds) == expected
    end

    test "all zeros packs to 36 zero bytes" do
      assert PythonBench.pack(List.duplicate(0, 24)) == :binary.copy(<<0>>, 36)
    end
  end
end
